## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/obesityLogic.ts`

```typescript
/**
 * Obesity Management Clinical Compass™ — Decision Support Logic
 * Based on:
 * - ASMBS/IFSO 2022 Indications for Metabolic and Bariatric Surgery (PMID: 35853783)
 * - AHA/ACC/AACVPR/AAPA/ABC/ACPM/ADA/AGS/APhA/ASPC/NLA/PCNA 2023 Obesity Guideline (PMID: 37228131)
 * - ASGE 2023 Endoscopic Bariatric and Metabolic Therapies Guideline (PMID: 37230994)
 * - FDA 2021 Approval of Semaglutide (Wegovy) for Obesity
 * - SURMOUNT-1 (tirzepatide), STEP-1 (semaglutide), OASIS-1 (ESG) trials
 */

// ─── Input Types ─────────────────────────────────────────────────────────────

export type BMICategory =
  | "overweight"       // 25-29.9
  | "obese_class1"     // 30-34.9
  | "obese_class2"     // 35-39.9
  | "obese_class3";    // ≥40

export type GLP1Response = "naive" | "inadequate" | "adequate" | "intolerant";
export type PriorBariatricSurgery = "none" | "band" | "sleeve" | "rygb" | "other";

export interface ObesityInput {
  // Anthropometrics
  bmi: number;
  waistCircumference: number; // cm
  // Comorbidities
  t2dm: boolean;
  hypertension: boolean;
  osa: boolean;
  nafld: boolean; // non-alcoholic fatty liver disease / MASLD
  gerd: boolean;
  dyslipidemia: boolean;
  cardiovascularDisease: boolean;
  heartFailure: boolean;
  // Prior treatments
  lifestyleInterventionAttempted: boolean; // ≥6 months
  glp1Attempted: boolean;
  glp1Response: GLP1Response;
  priorBariatricSurgery: PriorBariatricSurgery;
  // Patient factors
  age: number;
  sex: "male" | "female";
  pregnant: boolean;
  // Surgical risk
  surgicalRisk: "low" | "moderate" | "high" | "prohibitive";
  // Preferences
  patientPreference: "pharmacotherapy" | "endoscopic" | "surgical" | "no_preference";
  // Specific conditions
  ibd: boolean;
  cirrhosis: boolean;
  eatingDisorder: boolean;
  substanceAbuse: boolean;
}

// ─── Output Types ─────────────────────────────────────────────────────────────

export type TreatmentApproach =
  | "lifestyle_only"
  | "glp1_agonist"
  | "glp1_plus_lifestyle"
  | "esg_endoscopic"
  | "bariatric_surgery_sleeve"
  | "bariatric_surgery_rygb"
  | "bariatric_surgery_bpd_ds"
  | "revision_surgery"
  | "multidisciplinary";

export interface ObesityRecommendation {
  primaryApproach: TreatmentApproach;
  primaryLabel: string;
  alternativeApproaches: TreatmentApproach[];
  alternativeLabels: string[];
  // GLP-1 specifics
  glp1Agent?: string;
  glp1Rationale?: string;
  // Surgical specifics
  surgicalProcedure?: string;
  surgicalRationale?: string;
  // ESG specifics
  esgCriteria?: string[];
  // Weight loss targets
  expectedWeightLoss: string;
  // Contraindications
  contraindications: string[];
  // Key warnings
  keyWarnings: string[];
  // Next steps
  nextSteps: string[];
  // Rationale
  rationale: string;
  evidenceLevel: "Class I" | "Class IIa" | "Class IIb" | "Class III";
  guidelineSource: string;
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

export function classifyBMI(bmi: number): BMICategory {
  if (bmi < 30) return "overweight";
  if (bmi < 35) return "obese_class1";
  if (bmi < 40) return "obese_class2";
  return "obese_class3";
}

export function countComorbidities(input: ObesityInput): number {
  return [
    input.t2dm, input.hypertension, input.osa, input.nafld,
    input.gerd, input.dyslipidemia, input.cardiovascularDisease,
  ].filter(Boolean).length;
}

export function isSurgicalCandidate(input: ObesityInput): boolean {
  if (input.pregnant) return false;
  if (input.surgicalRisk === "prohibitive") return false;
  if (input.substanceAbuse) return false;
  // ASMBS 2022: BMI ≥35 with comorbidities, or BMI ≥40 regardless
  if (input.bmi >= 40) return true;
  if (input.bmi >= 35 && countComorbidities(input) >= 1) return true;
  // ASMBS 2022 expanded: BMI 30-34.9 with T2DM or metabolic syndrome
  if (input.bmi >= 30 && input.t2dm) return true;
  return false;
}

export function isESGCandidate(input: ObesityInput): boolean {
  if (input.pregnant) return false;
  if (input.cirrhosis) return false;
  if (input.priorBariatricSurgery !== "none") return false;
  // ASGE 2023: BMI 30-50, failed lifestyle ± pharmacotherapy
  return input.bmi >= 30 && input.bmi <= 50 && input.lifestyleInterventionAttempted;
}

export function selectGLP1Agent(input: ObesityInput): { agent: string; rationale: string } {
  // Tirzepatide (GIP/GLP-1): SURMOUNT-1 — 22.5% weight loss
  if (input.t2dm && input.cardiovascularDisease) {
    return {
      agent: "Tirzepatide (Zepbound) 2.5 mg → 15 mg weekly — preferred for T2DM + CVD",
      rationale: "SURMOUNT-1: 22.5% mean body weight reduction at 72 weeks. SURPASS-CVOT: superior CV outcomes vs dulaglutide in T2DM.",
    };
  }
  if (input.t2dm) {
    return {
      agent: "Tirzepatide (Zepbound) or Semaglutide (Ozempic 2 mg for T2DM) — both FDA-approved",
      rationale: "SURMOUNT-2 (tirzepatide in T2DM): 15.7% weight loss. STEP-2 (semaglutide in T2DM): 9.6% weight loss.",
    };
  }
  if (input.cardiovascularDisease) {
    return {
      agent: "Semaglutide (Wegovy) 2.4 mg weekly — SELECT trial: 20% CV event reduction",
      rationale: "SELECT trial: semaglutide 2.4 mg reduced MACE by 20% in overweight/obese patients with established CVD (no T2DM).",
    };
  }
  // Default: tirzepatide preferred for weight loss efficacy
  return {
    agent: "Tirzepatide (Zepbound) 2.5 mg → 15 mg weekly — highest weight loss efficacy",
    rationale: "SURMOUNT-1: 22.5% mean weight loss vs 2.4% placebo at 72 weeks. Superior to semaglutide in head-to-head SURMOUNT-5 trial.",
  };
}

// ─── Main Assessment Function ─────────────────────────────────────────────────

export function assessObesity(input: ObesityInput): ObesityRecommendation {
  const warnings: string[] = [];
  const nextSteps: string[] = [];
  const contraindications: string[] = [];
  const bmiCategory = classifyBMI(input.bmi);
  const comorbidityCount = countComorbidities(input);
  const surgicalCandidate = isSurgicalCandidate(input);
  const esgCandidate = isESGCandidate(input);
  const glp1Agent = selectGLP1Agent(input);

  // Contraindications
  if (input.pregnant) contraindications.push("Pregnancy: all pharmacotherapy and surgical/endoscopic interventions contraindicated");
  if (input.eatingDisorder) contraindications.push("Active eating disorder: requires psychiatric evaluation and treatment before any intervention");
  if (input.substanceAbuse) contraindications.push("Active substance abuse: contraindication to bariatric surgery until sustained sobriety achieved");
  if (input.cirrhosis) contraindications.push("Cirrhosis: ESG contraindicated; bariatric surgery requires hepatology evaluation");

  // Warnings
  if (input.gerd && input.priorBariatricSurgery === "none") {
    warnings.push("GERD: sleeve gastrectomy may worsen GERD — RYGB preferred if GERD is significant");
  }
  if (input.nafld) {
    warnings.push("MASLD/NAFLD: bariatric surgery is most effective treatment — consider prioritizing surgical referral");
  }
  if (input.heartFailure) {
    warnings.push("Heart failure: GLP-1 agonists (semaglutide) have demonstrated benefit in HFpEF (STEP-HFpEF trial) — consider prioritizing pharmacotherapy");
  }
  if (input.glp1Response === "inadequate" && input.glp1Attempted) {
    warnings.push("Inadequate GLP-1 response: escalate to maximum tolerated dose before switching — consider bariatric surgery if BMI criteria met");
  }
  if (input.bmi >= 50) {
    warnings.push("BMI ≥50: BPD/DS may offer superior weight loss but higher complication risk — discuss with experienced bariatric center");
  }

  // ── Overweight / Class 1 without comorbidities ──
  if (input.bmi < 30 || (bmiCategory === "obese_class1" && comorbidityCount === 0 && !input.t2dm)) {
    nextSteps.push("Intensive behavioral therapy: ≥14 sessions in 6 months (AHA/ACC 2023 Class I)");
    nextSteps.push("Dietary counseling: caloric deficit 500-1000 kcal/day");
    nextSteps.push("Physical activity: ≥150 min/week moderate-intensity aerobic exercise");
    return {
      primaryApproach: "lifestyle_only",
      primaryLabel: "Intensive Lifestyle Intervention",
      alternativeApproaches: [],
      alternativeLabels: [],
      expectedWeightLoss: "5-10% body weight with sustained lifestyle modification",
      contraindications,
      keyWarnings: warnings,
      nextSteps,
      rationale: "BMI <30 or Class I obesity without comorbidities: lifestyle intervention is first-line per AHA/ACC 2023. Pharmacotherapy considered if BMI ≥30 or ≥27 with comorbidities.",
      evidenceLevel: "Class I",
      guidelineSource: "AHA/ACC 2023 Obesity Guideline (PMID: 37228131)",
    };
  }

  // ── BMI ≥27 with comorbidities or BMI ≥30 — pharmacotherapy indicated ──
  if (!input.glp1Attempted || input.glp1Response === "naive") {
    nextSteps.push(`Initiate ${glp1Agent.agent}`);
    nextSteps.push("Titrate dose over 16-20 weeks to maximum tolerated dose");
    nextSteps.push("Reassess weight loss at 16 weeks: if <5%, consider switching agent or escalating to surgical/endoscopic therapy");
    nextSteps.push("Intensive lifestyle counseling concurrent with pharmacotherapy");
    if (surgicalCandidate && input.bmi >= 35) {
      nextSteps.push("Discuss bariatric surgery as definitive option — refer to bariatric surgery center for evaluation");
    }
    return {
      primaryApproach: "glp1_plus_lifestyle",
      primaryLabel: "GLP-1/GIP Agonist + Intensive Lifestyle Intervention",
      alternativeApproaches: esgCandidate ? ["esg_endoscopic", "bariatric_surgery_sleeve"] : ["bariatric_surgery_sleeve"],
      alternativeLabels: esgCandidate
        ? ["Endoscopic Sleeve Gastroplasty (ESG) — if pharmacotherapy fails/intolerable", "Sleeve Gastrectomy — if BMI criteria met"]
        : ["Sleeve Gastrectomy — if BMI criteria met"],
      glp1Agent: glp1Agent.agent,
      glp1Rationale: glp1Agent.rationale,
      expectedWeightLoss: input.t2dm ? "9-16% body weight (tirzepatide/semaglutide in T2DM)" : "15-22% body weight (tirzepatide SURMOUNT-1)",
      contraindications,
      keyWarnings: warnings,
      nextSteps,
      rationale: `GLP-1/GIP agonists are first-line pharmacotherapy for BMI ≥30 (or ≥27 with comorbidities) per AHA/ACC 2023. ${glp1Agent.rationale}`,
      evidenceLevel: "Class I",
      guidelineSource: "AHA/ACC 2023 (PMID: 37228131); ASMBS/IFSO 2022 (PMID: 35853783)",
    };
  }

  // ── GLP-1 intolerant or inadequate response ──
  if (input.glp1Response === "intolerant" || input.glp1Response === "inadequate") {
    // ESG option
    if (esgCandidate && (input.bmi >= 30 && input.bmi < 40) && input.surgicalRisk !== "low") {
      nextSteps.push("Endoscopic sleeve gastroplasty (ESG): outpatient procedure, 15-18% total body weight loss at 24 months");
      nextSteps.push("Pre-procedure: upper endoscopy, nutritional counseling, anesthesia evaluation");
      nextSteps.push("Post-procedure: liquid diet 2 weeks → soft diet 2 weeks → regular diet");
      nextSteps.push("Concurrent lifestyle modification and nutritional supplementation");
      return {
        primaryApproach: "esg_endoscopic",
        primaryLabel: "Endoscopic Sleeve Gastroplasty (ESG)",
        alternativeApproaches: surgicalCandidate ? ["bariatric_surgery_sleeve", "bariatric_surgery_rygb"] : ["glp1_agonist"],
        alternativeLabels: surgicalCandidate
          ? ["Sleeve Gastrectomy (if BMI ≥35 with comorbidities)", "RYGB (if GERD present or BMI ≥40)"]
          : ["Alternative GLP-1 agent (tirzepatide if semaglutide failed, or vice versa)"],
        esgCriteria: [
          "BMI 30-50 kg/m²",
          "Failed ≥6 months lifestyle intervention",
          "No prior bariatric surgery",
          "No cirrhosis or portal hypertension",
          "Willing to comply with post-procedure diet",
        ],
        expectedWeightLoss: "15-18% total body weight at 24 months (OASIS-1 trial)",
        contraindications,
        keyWarnings: warnings,
        nextSteps,
        rationale: "ESG is a minimally invasive endoscopic bariatric procedure. OASIS-1 trial: 13.6% total body weight loss vs 0.8% sham at 52 weeks. FDA approved 2024 for BMI ≥30.",
        evidenceLevel: "Class IIa",
        guidelineSource: "ASGE 2023 (PMID: 37230994); ASMBS/IFSO 2022 (PMID: 35853783)",
      };
    }

    // Surgical options
    if (surgicalCandidate) {
      const preferRYGB = input.gerd || input.bmi >= 50 || input.t2dm;
      const procedure = preferRYGB ? "bariatric_surgery_rygb" : "bariatric_surgery_sleeve";
      nextSteps.push("Bariatric surgery evaluation: multidisciplinary team (surgery, nutrition, psychology, medicine)");
      nextSteps.push("Pre-operative workup: EGD, sleep study, cardiac evaluation if indicated");
      nextSteps.push("Nutritional supplementation: multivitamin, calcium, vitamin D, B12 — lifelong");
      nextSteps.push(preferRYGB
        ? "RYGB: preferred for GERD, T2DM, or BMI ≥50 — superior glycemic control and GERD resolution"
        : "Sleeve gastrectomy: simpler procedure, lower complication rate — avoid if significant GERD");
      return {
        primaryApproach: procedure,
        primaryLabel: preferRYGB
          ? "Roux-en-Y Gastric Bypass (RYGB) — preferred"
          : "Sleeve Gastrectomy — preferred",
        alternativeApproaches: preferRYGB
          ? ["bariatric_surgery_sleeve", "esg_endoscopic"]
          : ["bariatric_surgery_rygb", "esg_endoscopic"],
        alternativeLabels: preferRYGB
          ? ["Sleeve Gastrectomy (if GERD not severe)", "ESG (if surgical risk high)"]
          : ["RYGB (if GERD present or T2DM)", "ESG (if surgical risk high)"],
        surgicalProcedure: preferRYGB ? "Roux-en-Y Gastric Bypass" : "Sleeve Gastrectomy",
        surgicalRationale: preferRYGB
          ? "RYGB: 30-35% total body weight loss, superior T2DM remission (80%), and GERD resolution. Preferred for GERD, T2DM, BMI ≥50."
          : "Sleeve gastrectomy: 25-30% total body weight loss, simpler anatomy, lower malabsorption risk.",
        expectedWeightLoss: preferRYGB ? "30-35% total body weight at 2 years" : "25-30% total body weight at 2 years",
        contraindications,
        keyWarnings: warnings,
        nextSteps,
        rationale: `Bariatric surgery is the most effective long-term treatment for severe obesity. ASMBS/IFSO 2022 expanded indications: BMI ≥35 with any comorbidity, or BMI ≥30 with T2DM. ${preferRYGB ? "RYGB preferred for GERD/T2DM." : "Sleeve gastrectomy for BMI 35-49 without significant GERD."}`,
        evidenceLevel: "Class I",
        guidelineSource: "ASMBS/IFSO 2022 (PMID: 35853783); AHA/ACC 2023 (PMID: 37228131)",
      };
    }

    // Not surgical candidate — try alternative GLP-1
    nextSteps.push("Consider alternative GLP-1 agent (tirzepatide if semaglutide failed, or vice versa)");
    nextSteps.push("Orlistat 120 mg TID with meals — modest weight loss (2.9 kg vs placebo)");
    nextSteps.push("Naltrexone/bupropion (Contrave) — if GLP-1 not tolerated");
    nextSteps.push("Intensive behavioral therapy: ≥14 sessions in 6 months");
    return {
      primaryApproach: "glp1_agonist",
      primaryLabel: "Alternative GLP-1 Agent or Combination Pharmacotherapy",
      alternativeApproaches: ["lifestyle_only"],
      alternativeLabels: ["Intensive Lifestyle Intervention + Behavioral Therapy"],
      glp1Agent: "Alternative agent: Tirzepatide (if semaglutide failed) or Semaglutide (if tirzepatide failed)",
      glp1Rationale: "Class switch may improve tolerability and efficacy. Consider lower starting dose and slower titration.",
      expectedWeightLoss: "5-15% body weight depending on agent and tolerability",
      contraindications,
      keyWarnings: [...warnings, "Surgical risk prohibitive: pharmacotherapy and lifestyle modification are primary options"],
      nextSteps,
      rationale: "For patients with inadequate GLP-1 response or intolerance who are not surgical candidates, consider alternative agents or combination pharmacotherapy.",
      evidenceLevel: "Class IIa",
      guidelineSource: "AHA/ACC 2023 (PMID: 37228131)",
    };
  }

  // ── Revision surgery ──
  if (input.priorBariatricSurgery !== "none") {
    nextSteps.push("Evaluate cause of weight regain: dietary non-compliance, anatomic issue, or metabolic adaptation");
    nextSteps.push("Upper endoscopy to assess anatomy");
    nextSteps.push("Consider revision surgery: RYGB after failed sleeve, or band removal + conversion");
    nextSteps.push("GLP-1 agonist as adjunct to revision surgery or as alternative");
    return {
      primaryApproach: "revision_surgery",
      primaryLabel: "Revision Bariatric Surgery Evaluation",
      alternativeApproaches: ["glp1_plus_lifestyle"],
      alternativeLabels: ["GLP-1 Agonist + Lifestyle (as adjunct or alternative to revision)"],
      expectedWeightLoss: "Variable — depends on revision procedure and compliance",
      contraindications,
      keyWarnings: [...warnings, "Revision surgery carries higher complication risk than primary bariatric surgery — ensure experienced center"],
      nextSteps,
      rationale: "Weight regain after bariatric surgery is common. Revision surgery or pharmacotherapy (GLP-1 agonists) are effective options. Multidisciplinary evaluation essential.",
      evidenceLevel: "Class IIa",
      guidelineSource: "ASMBS/IFSO 2022 (PMID: 35853783)",
    };
  }

  // Default: multidisciplinary evaluation
  return {
    primaryApproach: "multidisciplinary",
    primaryLabel: "Multidisciplinary Obesity Management Program",
    alternativeApproaches: ["glp1_plus_lifestyle", "bariatric_surgery_sleeve"],
    alternativeLabels: ["GLP-1 Agonist + Lifestyle", "Bariatric Surgery (if criteria met)"],
    expectedWeightLoss: "10-20% body weight with comprehensive program",
    contraindications,
    keyWarnings: warnings,
    nextSteps: [
      "Comprehensive obesity evaluation: metabolic panel, thyroid, sleep study",
      "Multidisciplinary team: obesity medicine, nutrition, behavioral health, exercise physiology",
      "Individualize treatment based on comorbidities, preferences, and prior treatment history",
    ],
    rationale: "Complex obesity management requires individualized multidisciplinary approach per AHA/ACC 2023.",
    evidenceLevel: "Class I",
    guidelineSource: "AHA/ACC 2023 (PMID: 37228131); ASMBS/IFSO 2022 (PMID: 35853783)",
  };
}

// ─── Utility Functions ─────────────────────────────────────────────────────────

export function getApproachColor(approach: TreatmentApproach): string {
  switch (approach) {
    case "lifestyle_only": return "bg-green-900/40 border-green-600 text-green-300";
    case "glp1_agonist":
    case "glp1_plus_lifestyle": return "bg-blue-900/40 border-blue-600 text-blue-300";
    case "esg_endoscopic": return "bg-violet-900/40 border-violet-600 text-violet-300";
    case "bariatric_surgery_sleeve":
    case "bariatric_surgery_rygb":
    case "bariatric_surgery_bpd_ds": return "bg-emerald-900/40 border-emerald-600 text-emerald-300";
    case "revision_surgery": return "bg-amber-900/40 border-amber-600 text-amber-300";
    case "multidisciplinary": return "bg-teal-900/40 border-teal-600 text-teal-300";
    default: return "bg-slate-800/50 border-slate-600 text-slate-400";
  }
}

export function getBMILabel(bmi: number): string {
  if (bmi < 18.5) return "Underweight";
  if (bmi < 25) return "Normal weight";
  if (bmi < 30) return "Overweight";
  if (bmi < 35) return "Obese Class I";
  if (bmi < 40) return "Obese Class II";
  return "Obese Class III (Severe)";
}
